    addEventListener('keydown', onKey); addEventListener('pointerdown', onFirst, true); addEventListener('keydown', onFirst, true);
    document.querySelectorAll('a[href^="#"]').forEach((a) => a.addEventListener('click', () => { if (!R.contains(a) || !a.matches('[data-tour-gate]')) { input.checked = false; D.on = false; } }));
    D.start = () => { D.active = true; D.last = null; R.classList.add('is-drifting'); };
    this.cleanup = () => { removeEventListener('wheel', onWheel); removeEventListener('touchmove', onWheel); removeEventListener('keydown', onKey); removeEventListener('pointerdown', onFirst, true); removeEventListener('keydown', onFirst, true); sw.remove(); };
    const pxps = () => this.stage.clientHeight * .3;
    const loop = (now) => {
      if (!this.alive) return;
      const dt = Math.min(.05, (now - D.lt) / 1000 || 0); D.lt = now;
      const endY = top() + span();
      if (D.active && D.on && !D.done && scrollY < endY - 1) {
        if (D.last !== null && Math.abs(scrollY - D.last) > 40) D.pos = scrollY;     // a scrollbar drag: carry on from there
        else if (D.last === null) D.pos = scrollY;
        D.pos = Math.min(endY, D.pos + pxps() * dt);
        scrollTo({ top: D.pos, behavior: 'instant' }); D.last = D.pos;
      }
      if (D.active && scrollY >= endY - 2) D.done = true;
      sw.classList.toggle('is-gone', !D.active || D.done);
      if (!this.frozen) this.render(tNow());
      requestAnimationFrame(loop);
    };
    requestAnimationFrame(loop);
  }

  /* swap in another script on the same window: the product goes back to how the page drew it, then the new
     script is compiled and measured. The playground uses it to turn a visitor's clicks into a live script. */
  load(script) {
    this.pause();
    for (const c of this.ch) { c.last = undefined; this.write(c, c.init); }
    this.S = script; this.compile();
    Object.assign(this.api, { duration: this.duration, chapters: this.chapters.map((c) => ({ t: c.start, n: c.n, title: c.title })), marks: this.marks });
    this.t = -1; this.layout(); this.grow(); this.probe();
    return this.api;
  }

  destroy() { this.alive = false; this.pause(); this.ro?.disconnect(); this.cleanup?.(); this.audio?.pause(); }
}

/* demo/canvas: the board. The whole site is one sheet of warm paper the camera flies across (tour.js), then the visitor
   takes over: drag to pan, wheel or pinch to zoom, arrows frame to frame, a minimap. On phones (≤ 700 px) the same items
   become a vertical sequence (.cv-seq). Positions live on each item as CSS variables (section.html). */
@import url('../tour/tour.css');

.demo-canvas{
  --cv-paper:#f3f0ea; --cv-dot:rgba(25,24,22,.14); --cv-accent:#b9542e; --cv-sticky:#ece2c8; --cv-sticky-ink:#4d463c;
  --cv-shadow:0 1px 0 rgba(25,24,22,.04),0 22px 44px -30px rgba(25,24,22,.42),0 8px 16px -12px rgba(25,24,22,.16);
  --tour-stage:var(--cv-paper); --tour-ring:rgba(185,84,46,.5);
  position:relative;background:var(--cv-paper)}
.demo-canvas .cv-stage{background:var(--cv-paper);touch-action:none;cursor:default}
.demo-canvas.cv-yours .cv-stage{cursor:grab}
.demo-canvas.cv-yours.is-dragging .cv-stage,.demo-canvas.cv-yours.is-dragging .cv-stage *{cursor:grabbing!important}
.cv-frame-all{position:absolute;inset:0;pointer-events:none}

/* ── the board ─────────────────────────────────────────────────────────── */
.demo-canvas [data-tour-window].cv-win{border-radius:0;box-shadow:none;overflow:visible;background:var(--cv-paper);
  background-image:radial-gradient(circle at 1.5px 1.5px,var(--cv-dot) 1.3px,transparent 1.9px);background-size:40px 40px;will-change:transform}
.cv-board{position:relative;width:100%;height:100%}
.cv-region{position:absolute;left:0;top:50%;width:3200px;height:1700px;margin-top:-850px}
.is-square .cv-region{width:1800px;height:1800px;margin-top:-900px}
.is-tall .cv-region{width:1200px;height:2120px;margin-top:-1060px}

.cv-item{position:absolute;left:calc(var(--x) * 1px);top:calc(var(--y) * 1px);width:calc(var(--w) * 1px);height:calc(var(--h) * 1px)}
.is-square .cv-item{left:calc(var(--sx) * 1px);top:calc(var(--sy) * 1px);width:calc(var(--sw) * 1px);height:calc(var(--sh) * 1px)}
.is-tall .cv-item{left:calc(var(--tx) * 1px);top:calc(var(--ty) * 1px);width:calc(var(--tw) * 1px);height:calc(var(--th) * 1px)}
.cv-zone{position:absolute;pointer-events:none;visibility:hidden}

/* frames: a white placeholder with its name above it, the way a board labels frames */
.cv-frame{border-radius:3px}
.cv-frame::before{content:attr(data-label);position:absolute;left:1px;bottom:calc(100% + 12px);font:500 17px/1 var(--sans);letter-spacing:.01em;color:var(--ink-3);white-space:nowrap}
.cv-frame > .ph:not(.cv-portrait){position:absolute;inset:0;aspect-ratio:auto;border-radius:3px;box-shadow:inset 0 0 0 1px var(--ph-line),var(--cv-shadow)}
.cv-frame > .ph::after{font-size:13px}
.cv-about > .cv-portrait{position:relative;inset:auto}
.cv-tall > .ph{border-radius:18px}
.cv-frame{transition:box-shadow .5s var(--ease)}
.cv-yours .cv-frame:hover > .ph,.cv-yours .cv-frame.is-at > .ph{box-shadow:inset 0 0 0 1px var(--ph-line),0 0 0 1.5px var(--ink-3),var(--cv-shadow)}
.cv-yours .cv-frame{cursor:zoom-in}
.cv-yours .cv-frame.is-at{cursor:zoom-out}

/* the cover: the name, set like a title frame */
.cv-cover{background:var(--ph);box-shadow:inset 0 0 0 1px var(--ph-line),var(--cv-shadow);container-type:size}
.cv-cover-in{position:absolute;inset:0;display:flex;flex-direction:column;padding:7.5cqh 7cqw 6cqh}
.cv-eyebrow{margin:0;font:500 max(13px,1.9cqw)/1 var(--sans);letter-spacing:.16em;text-transform:uppercase;color:var(--ink-3)}
.cv-name{margin:auto 0 0;font:300 min(18cqw,40cqh)/.9 var(--serif);letter-spacing:-.035em;color:var(--ink)}
.cv-name em{font-style:italic;font-weight:300}
.cv-line{margin:4cqh 0 0;max-width:30em;font:400 max(15px,min(3cqw,6cqh))/1.35 var(--sans);color:var(--ink-2);text-wrap:balance}
.cv-meta{display:flex;justify-content:space-between;gap:20px;margin:auto 0 0;padding-top:2.6cqh;border-top:1px solid var(--ph-line);font:500 max(12px,min(1.75cqw,3.6cqh))/1 var(--sans);letter-spacing:.04em;color:var(--ink-3)}
.cv-meta-hint{opacity:0;transition:opacity .6s}
.cv-yours:not(.cv-moved) .cv-meta-hint{opacity:1}

/* group heads: a number, a name, a quiet meta line, a hairline under them */
.cv-head{display:flex;align-items:baseline;gap:18px;padding-bottom:14px;border-bottom:1px solid var(--rule)}
.cv-head h2{margin:0;font:400 44px/1 var(--serif);letter-spacing:-.02em;color:var(--ink);white-space:nowrap}
.cv-num{font:500 16px/1 var(--sans);letter-spacing:.08em;color:var(--cv-accent);font-variant-numeric:tabular-nums}
.cv-yr{margin-left:auto;font:400 16px/1 var(--sans);color:var(--ink-3);white-space:nowrap}
.is-tall .cv-head h2,.is-square .cv-head h2{font-size:38px}

/* sticky notes, in a calm hand */
.cv-note{container-type:size;transform:rotate(calc(var(--rot,0) * 1deg));background:var(--cv-sticky);border-radius:2px;
  box-shadow:0 1px 1px rgba(25,24,22,.08),0 16px 26px -18px rgba(25,24,22,.45);display:flex;align-items:center;padding:20px 26px}
.cv-note::before{content:"";position:absolute;left:50%;top:-11px;width:34%;height:24px;margin-left:-17%;background:rgba(255,255,255,.5);box-shadow:0 0 0 1px rgba(25,24,22,.04);transform:rotate(-2deg)}
.cv-note p{margin:0;font:italic 400 min(14cqw,24cqh)/1.18 var(--serif);color:var(--cv-sticky-ink);letter-spacing:-.005em;text-wrap:balance}

/* hairline arrows (section.js writes each d); --draw 0 → 1 draws one in */
.cv-arrows{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none}
.cv-arrows path{fill:none;stroke:var(--ink-3);stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:1 1;stroke-dashoffset:calc(1 - var(--draw,1))}
.cv-arrows path.is-hand{stroke:var(--cv-accent);stroke-width:2;opacity:.75}

/* comment pins: dropped by the cursor in the tour, and there for good once it's done */
.cv-pin{--in:0;position:absolute;z-index:3;left:calc(var(--px) * 100%);top:calc(var(--py) * 100%);width:0;height:0;opacity:min(1,calc(var(--in) * 3))}
.cv-pin i{position:absolute;left:0;bottom:0;display:grid;place-items:center;width:40px;height:40px;border-radius:50% 50% 50% 0;background:var(--cv-accent);
  box-shadow:0 0 0 3px #fff,0 8px 18px -6px rgba(25,24,22,.5);font:600 13px/1 var(--sans);font-style:normal;letter-spacing:.02em;color:#fff;
  transform-origin:0 100%;transform:scale(calc(.4 + .6 * var(--in)))}
.cv-pin p{position:absolute;left:54px;bottom:-6px;margin:0;width:max-content;max-width:330px;padding:12px 16px 14px;border-radius:12px;background:#fff;
  box-shadow:0 0 0 1px var(--ph-line),0 18px 36px -18px rgba(25,24,22,.4);font:400 20px/1.35 var(--sans);color:var(--ink);
  opacity:clamp(0,calc(var(--in) * 2 - 1),1);transform:translateX(calc((1 - var(--in)) * -10px));transform-origin:0 100%}
.cv-pin p b{display:block;margin-bottom:5px;font:500 13px/1 var(--sans);letter-spacing:.02em;color:var(--ink-3)}
.cv-pin.is-left p{left:auto;right:12px;bottom:52px;transform-origin:100% 100%}
.cv-pin.is-up p{bottom:52px}
.cv-pin span.is-caret::after{content:"";display:inline-block;width:2px;height:1.05em;margin-left:2px;vertical-align:-.16em;background:var(--cv-accent)}

/* about */
.cv-about{background:var(--ph);box-shadow:inset 0 0 0 1px var(--ph-line),var(--cv-shadow);container-type:size;display:grid;grid-template-columns:42% 1fr;gap:44px;padding:44px;align-items:start}
.cv-portrait{width:100%;box-shadow:inset 0 0 0 1px var(--ph-line)}
.cv-portrait::after{display:none}
.cv-k{margin:0 0 1.2em;font:500 max(11px,1.9cqw)/1 var(--sans);letter-spacing:.16em;text-transform:uppercase;color:var(--ink-3)}
.cv-bio{margin:0 0 1.8em;font:400 max(14px,min(3.5cqw,5.6cqh))/1.36 var(--serif);color:var(--ink);text-wrap:pretty}
.cv-list{list-style:none;margin:0;padding:0;font:400 max(11px,min(2.3cqw,3.8cqh))/1.3 var(--sans);color:var(--ink-2)}
.cv-list li{display:flex;justify-content:space-between;gap:12px;padding:.6em 0;border-top:1px solid var(--ph-line);font-variant-numeric:tabular-nums}
.cv-list li span+span{color:var(--ink-3)}

/* contact */
.cv-contact{background:var(--ph);box-shadow:inset 0 0 0 1px var(--ph-line),var(--cv-shadow);container-type:size;padding:44px 50px 42px;display:flex;flex-direction:column}
.cv-mail{display:block;margin:0;font:400 min(7.4cqw,15cqh)/1.05 var(--serif);letter-spacing:-.02em;color:var(--ink);text-decoration:none;word-break:break-word}
.cv-mail:hover,.cv-mail.is-hover{text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:.14em}
.cv-open{margin:1.1em 0 0;max-width:28em;font:400 max(13px,min(2.5cqw,4.6cqh))/1.4 var(--sans);color:var(--ink-2)}
.cv-links{list-style:none;display:flex;flex-wrap:wrap;gap:6px 22px;margin:auto 0 0;padding:0;font:500 max(12px,min(2.3cqw,4.2cqh))/1 var(--sans)}
.cv-links a{color:var(--ink);text-decoration:none;box-shadow:inset 0 -1px 0 var(--rule)}
.cv-links a:hover{box-shadow:inset 0 -1px 0 var(--ink)}
.cv-domain{position:absolute;right:7cqw;top:9cqh;margin:0;font:500 max(11px,1.8cqw)/1 var(--sans);letter-spacing:.06em;color:var(--ink-3)}
.cv-contact .cv-k{margin-bottom:1.6em}

/* ── the visitor's controls (stage px, not scaled) ───────────────────────── */
.cv-top,.cv-dock,.cv-skip,.cv-stage-note{position:absolute;z-index:10}
.cv-top{left:16px;right:16px;top:14px;display:flex;align-items:center;justify-content:space-between;gap:12px;pointer-events:none}
.cv-top button,.cv-zoom button,.cv-skip{pointer-events:auto;display:inline-flex;align-items:center;gap:7px;height:34px;padding:0 13px;border:0;border-radius:17px;cursor:pointer;
  background:color-mix(in srgb,var(--cv-paper) 86%,transparent);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);
  box-shadow:0 0 0 1px rgba(25,24,22,.08);font:500 13px/1 var(--sans);color:var(--ink-2);transition:background-color .3s,color .3s,box-shadow .3s}
.cv-top button:hover,.cv-zoom button:hover,.cv-skip:hover{color:var(--ink);box-shadow:0 0 0 1px rgba(25,24,22,.22)}
.cv-top .cv-me{font:400 18px/1 var(--serif);letter-spacing:-.01em;color:var(--ink);padding:0 15px}
.cv-nav{display:flex;gap:6px}
.cv-replay svg,.cv-zoom svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.cv-top button:focus-visible,.cv-zoom button:focus-visible,.cv-skip:focus-visible{outline:2px solid var(--cv-accent);outline-offset:2px}
.cv-dock{right:16px;bottom:16px;display:flex;flex-direction:column;align-items:flex-end;gap:8px}
.cv-mini{position:relative;width:180px;border-radius:6px;overflow:hidden;cursor:pointer;background:color-mix(in srgb,var(--cv-paper) 88%,transparent);
  -webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);box-shadow:0 0 0 1px rgba(25,24,22,.1),0 10px 24px -16px rgba(25,24,22,.35);touch-action:none}
.cv-mini-svg{display:block;width:100%;height:100%}
.cv-mini-svg rect{fill:#fff;stroke:rgba(25,24,22,.2);stroke-width:1;vector-effect:non-scaling-stroke}
.cv-mini-svg rect.is-note{fill:var(--cv-sticky);stroke:none}
.cv-mini-svg rect.is-head{fill:rgba(25,24,22,.18);stroke:none}
.cv-mini-view{position:absolute;left:0;top:0;border-radius:2px;box-shadow:0 0 0 1.5px var(--cv-accent),0 0 0 9999px rgba(243,240,234,.42);pointer-events:none}
.cv-mini{transition:opacity .5s var(--ease),transform .6s var(--ease)}
.cv-whole .cv-mini{opacity:0;transform:translateY(8px);pointer-events:none}
.cv-zoom{display:flex;gap:4px}
.cv-zoom button{width:34px;padding:0;justify-content:center}
.cv-zoom .cv-pct{width:auto;min-width:58px;padding:0 10px;font-variant-numeric:tabular-nums}
.cv-skip{left:16px;bottom:16px}
.cv-stage-note{left:50%;bottom:22px;transform:translateX(-50%);max-width:min(30em,calc(100% - 420px))}

/* when they show: the controls arrive with the hand-over; the skip button only while the tour plays */
.cv-top,.cv-dock{opacity:0;transform:translateY(6px);transition:opacity .7s var(--ease),transform .9s var(--ease)}
.cv-top{transform:translateY(-6px)}
.cv-yours .cv-top,.cv-yours .cv-dock{opacity:1;transform:none}
.cv-top *,.cv-dock *{visibility:hidden}
.cv-yours .cv-top *,.cv-yours .cv-dock *{visibility:visible}
.cv-skip{opacity:0;pointer-events:none;transition:opacity .5s}
.demo-canvas.is-playing:not(.cv-yours) .cv-skip{opacity:1;pointer-events:auto}
.cv-yours .cv-stage-note,.is-playing .cv-stage-note{opacity:0;transition:opacity .4s}

/* the closing frame: a quiet line on how to move (live); the address (record) */
.cv-end{position:absolute;z-index:9;left:16px;bottom:16px;pointer-events:none;opacity:var(--in,0)}
.cv-hint{display:flex;flex-wrap:wrap;gap:6px;margin:0;font:500 12.5px/1 var(--sans);color:var(--ink-2);transition:opacity .8s}
.cv-hint span{display:inline-flex;align-items:center;gap:5px;height:30px;padding:0 12px;border-radius:15px;background:color-mix(in srgb,var(--cv-paper) 86%,transparent);box-shadow:0 0 0 1px rgba(25,24,22,.08)}
.cv-hint kbd{font:500 11px/1 var(--sans);padding:3px 5px;border-radius:4px;background:#fff;box-shadow:0 0 0 1px var(--ph-line)}
.cv-moved .cv-hint{opacity:0}
.cv-end-url{display:none}
@media (hover:none){.cv-hint span:last-child{display:none}.cv-hint span:first-child::after{content:" · pinch to zoom"}.cv-hint span:nth-child(2){display:none}}
html.tour-record .cv-end{left:0;right:0;bottom:calc(var(--su) * 4.2);display:flex;justify-content:center;transform:translateY(calc((1 - var(--in,0)) * 10px))}
html.tour-record .cv-hint{display:none}
html.tour-record .cv-end-url{display:block;margin:0;padding:calc(var(--su) * 1.3) calc(var(--su) * 2.4);border-radius:999px;background:var(--ink);color:var(--page);
  font:500 calc(var(--su) * 2.1)/1 var(--sans);letter-spacing:.01em}

/* the cursor's name tag, in the board's accent */
.demo-canvas .tour-tag{background:var(--cv-accent)}

/* ── phones: the same items as a vertical sequence ───────────────────────── */
.cv-seq .cv-stage{position:relative;height:auto;overflow:visible;touch-action:auto}
.cv-seq .tour-rig{position:static;clip-path:none!important}
.cv-seq [data-tour-window].cv-win{position:static;transform:none!important;width:auto!important;height:auto!important;background-size:28px 28px}
.cv-seq .cv-region{position:static;width:auto;height:auto;margin:0;display:grid;grid-template-columns:1fr 1fr;gap:56px 14px;padding:76px 16px 64px}
.cv-seq .cv-item{position:relative;left:auto;top:auto;width:auto;height:auto;grid-column:1 / -1;min-width:0}
.cv-seq .cv-arrows,.cv-seq .cv-zone,.cv-seq .cv-dock,.cv-seq .cv-skip,.cv-seq .cv-end,.cv-seq .tour-cur,.cv-seq .tour-ring,.cv-seq .tour-cap,.cv-seq .tour-card,.cv-seq .cv-nav{display:none!important}
.cv-seq .cv-top{position:fixed;opacity:1;transform:none;left:12px;right:auto;top:12px}
.cv-seq .cv-top *{visibility:visible}
.cv-seq .cv-top{opacity:0;transition:opacity .5s}
html.is-down .cv-seq .cv-top{opacity:1}
.cv-seq .cv-frame::before{position:static;display:block;margin:0 0 10px;font-size:13px}
.cv-seq .cv-frame > .ph:not(.cv-portrait){position:relative;inset:auto;aspect-ratio:var(--w) / var(--h)}
.cv-seq .cv-cover{height:auto;margin-top:8px;container-type:normal}
.cv-seq .cv-cover::before,.cv-seq .cv-about::before,.cv-seq .cv-contact::before{display:none}
.cv-seq .cv-cover-in{position:static;padding:30px 22px 22px;gap:0}
.cv-seq .cv-eyebrow{font-size:11px}
.cv-seq .cv-name{margin-top:64px;font-size:min(19vw,82px)}
.cv-seq .cv-line{margin-top:18px;font-size:17px}
.cv-seq .cv-meta{margin-top:40px;padding-top:14px;font-size:11.5px}
.cv-seq .cv-meta-hint{display:none}
.cv-seq .cv-note{width:min(72%,260px);height:auto;min-height:0;padding:30px 24px 26px;container-type:normal;justify-self:end;margin:-24px 4px -12px}
.cv-seq .cv-note:nth-of-type(odd){justify-self:start}
.cv-seq .cv-note p{font-size:22px}
.cv-seq .cv-head{margin-top:20px;margin-bottom:-28px;gap:12px;padding-bottom:12px}
.cv-seq .cv-head h2{font-size:30px;white-space:normal}
.cv-seq .cv-num,.cv-seq .cv-yr{font-size:12px}
.cv-seq .cv-tall{grid-column:auto}
.cv-seq .cv-pin{position:relative;left:auto;top:auto;width:auto;height:auto;opacity:1;display:flex;gap:10px;align-items:flex-start;margin-top:14px}
.cv-seq .cv-pin i{position:relative;flex:none;width:28px;height:28px;font-size:10px;transform:none;box-shadow:0 0 0 2px #fff}
.cv-seq .cv-pin p,.cv-seq .cv-pin.is-left p{position:relative;left:auto;right:auto;bottom:auto;opacity:1;transform:none;max-width:none;width:auto;font-size:15px;padding:10px 13px 11px;border-radius:10px}
.cv-seq .cv-pin p b{font-size:11px}
.cv-seq .cv-about{height:auto;display:block;padding:22px;container-type:normal}
.cv-seq .cv-portrait{width:56%;margin-bottom:22px}
.cv-seq .cv-k{font-size:11px}
.cv-seq .cv-bio{font-size:19px}
.cv-seq .cv-list{font-size:13px}
.cv-seq .cv-contact{height:auto;padding:26px 22px 24px;container-type:normal}
.cv-seq .cv-mail{font-size:clamp(26px,8.4vw,40px)}
.cv-seq .cv-open{font-size:15px}
.cv-seq .cv-links{margin-top:28px;font-size:14px}
.cv-seq .cv-domain{position:static;order:-1;margin-bottom:18px;font-size:11px}
.cv-seq .cv-stage-note{position:relative;left:auto;top:auto;bottom:auto;transform:none;display:flex;max-width:none;margin:0 16px 40px}

@media (prefers-reduced-motion:reduce){.cv-top,.cv-dock,.cv-skip,.cv-hint,.cv-frame{transition:none}}

/* StyleFeatures scaffolds: the shared placeholder kit.
   Every scaffold section links this first. Tokens can be overridden per site in site.json "theme". */
:root{
  --page:#f5f3ef;--page-2:#ece9e3;--ph:#ffffff;--ph-line:#e3dfd7;--ph-mark:#d9d4ca;
  --ink:#191816;--ink-2:#5f5a53;--ink-3:#9c968c;--rule:#d8d3c9;
  --note:#c2643f;--note-bg:#fbf1ea;
  --serif:'Newsreader',Georgia,serif;--sans:'Inter Tight',system-ui,-apple-system,sans-serif;--mono:ui-monospace,'SF Mono',Menlo,monospace;
  --gutter:clamp(16px,3.4vw,48px);--max:1280px;--radius:2px;
  --ease:cubic-bezier(.2,.7,.2,1);
}
*{box-sizing:border-box}
html{background:var(--page);-webkit-text-size-adjust:100%}
body{margin:0;background:var(--page);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased;overflow-x:hidden}
a{color:inherit}
img{display:block;max-width:100%}
.sf-wrap{max-width:var(--max);margin:0 auto;padding-inline:var(--gutter)}
.sf-sec{padding-block:clamp(72px,12vh,140px)}

/* ── type ───────────────────────────────────────────── */
.sf-eyebrow{margin:0 0 18px;font:500 12px/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}
.sf-h1{margin:0;font:400 clamp(44px,6.4vw,96px)/.98 var(--serif);letter-spacing:-.025em}
.sf-h2{margin:0;font:400 clamp(32px,4vw,58px)/1.02 var(--serif);letter-spacing:-.02em}
.sf-h3{margin:0;font:500 clamp(19px,1.6vw,23px)/1.2 var(--sans);letter-spacing:-.01em}
.sf-lede{margin:0;max-width:34em;font:400 clamp(17px,1.4vw,20px)/1.5 var(--sans);color:var(--ink-2)}
.sf-small{font:400 13px/1.45 var(--sans);color:var(--ink-3)}

/* ── placeholder image: <figure class="ph" style="--r:4/5" data-ph="Image · 4:5" data-hint="What goes here"></figure> */
.ph{position:relative;margin:0;aspect-ratio:var(--r,4/3);background:var(--ph);border-radius:var(--radius);overflow:hidden;
  box-shadow:inset 0 0 0 1px var(--ph-line);min-width:0}
.ph::before{content:"";position:absolute;inset:0;pointer-events:none;
  background:
    linear-gradient(to top right,transparent calc(50% - .5px),var(--ph-mark) calc(50% - .5px),var(--ph-mark) calc(50% + .5px),transparent calc(50% + .5px)),
    linear-gradient(to bottom right,transparent calc(50% - .5px),var(--ph-mark) calc(50% - .5px),var(--ph-mark) calc(50% + .5px),transparent calc(50% + .5px));
  opacity:.55}
.ph::after{content:attr(data-ph) "\A" attr(data-hint);white-space:pre-line;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  width:max-content;max-width:min(80%,24em);padding:9px 13px;background:var(--ph);text-align:center;
  font:500 11px/1.45 var(--sans);letter-spacing:.06em;text-transform:uppercase;color:var(--ink-3);border-radius:var(--radius)}
.ph[data-hint]::after{font-size:11px}
.ph.is-bare::after{content:none}
.ph.is-round{border-radius:50%}
.ph.is-tone{--ph:var(--page-2)}              /* a placeholder on a white card */
.ph > *{position:relative;z-index:1}

/* video placeholder: add .ph-video; scaffold.js adds the transport */
.ph-video{--ph:#f7f6f3}
.ph-video::before{opacity:.35}
.ph-video::after{top:auto;bottom:44px;transform:translateX(-50%);max-width:min(86%,26em)}   /* label sits low, clear of the play button */
.ph-play{position:absolute;z-index:2;left:50%;top:50%;width:56px;height:56px;margin:-28px 0 0 -28px;border:0;border-radius:50%;
  background:var(--ink);color:var(--page);cursor:pointer;display:grid;place-items:center;transition:transform .4s var(--ease)}
.ph-play:hover{transform:scale(1.06)}
.ph-play[hidden],.ph-bar[hidden]{display:none}
.ph-play svg{width:20px;height:20px}
.ph-play:focus-visible{outline:2px solid var(--note);outline-offset:4px}
.ph-bar{position:absolute;z-index:2;left:16px;right:16px;bottom:14px;display:flex;align-items:center;gap:12px;font:500 11px/1 var(--mono);color:var(--ink-3)}
.ph-track{flex:1;height:2px;background:var(--ph-line);position:relative;overflow:hidden}
.ph-track i{position:absolute;inset:0;background:var(--ink);transform-origin:left;transform:scaleX(var(--p,0))}
.ph-video.is-playing::before{animation:ph-breathe 3.2s ease-in-out infinite}
@keyframes ph-breathe{50%{opacity:.12}}

/* placeholder copy: <p class="ph-text" style="--n:3"></p>  (n lines, last one short) */
.ph-text{--lh:1.6em;display:block;margin:0;height:calc(var(--n,3) * var(--lh));max-width:32em;
  background:repeating-linear-gradient(to bottom,var(--ph-line) 0 .55em,transparent .55em var(--lh));
  -webkit-mask:linear-gradient(#000,#000) top/100% calc(100% - var(--lh)) no-repeat,linear-gradient(90deg,#000 var(--last,58%),transparent 0) bottom/100% var(--lh) no-repeat;
          mask:linear-gradient(#000,#000) top/100% calc(100% - var(--lh)) no-repeat,linear-gradient(90deg,#000 var(--last,58%),transparent 0) bottom/100% var(--lh) no-repeat}
.ph-logo{display:inline-flex;align-items:center;justify-content:center;height:34px;min-width:110px;padding:0 14px;border-radius:var(--radius);
  box-shadow:inset 0 0 0 1px var(--ph-line);background:var(--ph);font:600 11px/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}

/* ── controls ───────────────────────────────────────── */
.sf-btn{display:inline-flex;align-items:center;gap:10px;padding:14px 22px;border:0;border-radius:var(--radius);background:var(--ink);color:var(--page);
  font:500 14px/1 var(--sans);text-decoration:none;cursor:pointer;transition:background-color .3s ease,color .3s ease,box-shadow .3s ease}
.sf-btn:hover{background:#000}
.sf-btn--ghost{background:transparent;color:var(--ink);box-shadow:inset 0 0 0 1px var(--ink)}
.sf-btn--ghost:hover{background:var(--ink);color:var(--page)}
.sf-btn--text{padding:6px 0;background:none;color:var(--ink);box-shadow:inset 0 -1px 0 currentColor}
.sf-btn--text:hover{background:none;color:var(--ink-2)}
.sf-btn:focus-visible,.sf-field:focus-visible{outline:2px solid var(--note);outline-offset:3px}
.sf-field{width:100%;padding:14px 0;border:0;border-bottom:1px solid var(--rule);background:transparent;font:400 16px/1.2 var(--sans);color:var(--ink);border-radius:0}
.sf-field::placeholder{color:var(--ink-3)}
.sf-rule{height:0;border:0;border-top:1px solid var(--rule);margin:0}

/* ── notes: what goes here / who it suits. <span class="sf-note">Swap for your logo</span>; html.sf-clean hides them */
.sf-note{display:inline-flex;align-items:center;gap:7px;padding:5px 9px 5px 7px;border-radius:var(--radius);background:var(--note-bg);color:var(--note);
  font:500 11px/1.25 var(--sans);letter-spacing:.01em;vertical-align:middle;white-space:normal;max-width:30em}
.sf-note::before{content:"";flex:none;width:6px;height:6px;border-radius:50%;background:currentColor}
.sf-note.is-pin{position:absolute;z-index:5}
html.sf-clean .sf-note{display:none!important}

/* ── reveal ─────────────────────────────────────────── */
[data-reveal]{opacity:0;transform:translateY(14px);transition:opacity 1s var(--ease),transform 1.2s var(--ease);transition-delay:calc(var(--i,0) * 80ms)}
[data-reveal].is-in{opacity:1;transform:none}
.no-js [data-reveal]{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){[data-reveal]{opacity:1;transform:none;transition:none}}

/* ── preview spec card (only on preview pages) ───────── */
.sf-spec{position:fixed;z-index:9999;left:14px;bottom:14px;max-width:min(360px,calc(100vw - 28px));padding:14px 16px;border-radius:4px;
  background:rgba(255,255,255,.94);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);box-shadow:0 0 0 1px var(--ph-line),0 10px 30px -14px rgba(0,0,0,.3);
  font:400 12px/1.45 var(--sans);color:var(--ink-2)}
.sf-spec b{display:block;font:500 14px/1.25 var(--sans);color:var(--ink);margin:6px 0 3px}
.sf-spec .sf-kind{margin-right:6px}
.sf-spec ul{list-style:none;margin:8px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:5px}
.sf-spec li{padding:3px 7px;border-radius:2px;background:var(--page);color:var(--ink-2);font-size:11px}
.sf-spec button{margin-top:10px;padding:0;border:0;background:none;font:500 11px/1 var(--sans);color:var(--ink-3);text-decoration:underline;cursor:pointer}
.sf-spec.is-min p,.sf-spec.is-min ul{display:none}
.sf-thumb .sf-spec{display:none}
@media (max-width:700px){.sf-spec{left:8px;bottom:8px;padding:10px 12px}}
.sf-kind{display:inline-flex;align-items:center;gap:6px;padding:4px 8px 4px 7px;border-radius:2px;font:600 10px/1 var(--sans);letter-spacing:.12em;text-transform:uppercase}
.sf-kind::before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor}
.sf-kind--static{background:#eceae5;color:#6f6a62}
.sf-kind--interactive{background:#fbeee6;color:#b65a35}
.sf-kind--video{background:#1d1c1a;color:#f2efe9}

/* tour.css: the engine's own look. Window chromes, the cursor, ripples, chapter card, caption, key caps,
   the play controls, the auto-play switch and the ?record stage. Shared by every demo film; a template
   restyles it through these tokens rather than editing it:
     --tour-stage  backdrop behind the window        --tour-win-radius  window corners (design px)
     --tour-ring   click ripple colour               --tour-cap-bg / --tour-cap-ink  caption pill
   Sizes on the stage scale with --su (a hundredth of the stage's short side, set by tour.js). */

[data-tour-root]{position:relative;--tour-stage:var(--page-2,#ece9e3);--tour-ring:rgba(25,24,22,.42);--tour-cap-bg:var(--ink,#191816);--tour-cap-ink:var(--page,#f5f3ef);--tour-win-radius:12px}
[data-tour-stage]{position:sticky;top:0;height:100svh;overflow:hidden;background:var(--tour-stage);isolation:isolate;--su:9px}
[data-tour-root].is-play [data-tour-stage],[data-tour-root].is-still [data-tour-stage]{position:relative}
.tour-rig{position:absolute;inset:0}

/* the window: design pixels, scaled by the camera */
[data-tour-window]{position:absolute;left:0;top:0;transform-origin:0 0;display:flex;flex-direction:column;overflow:hidden;
  border-radius:var(--tour-win-radius);background:var(--ph,#fff);
  box-shadow:0 0 0 1px rgba(25,24,22,.12),0 40px 90px -40px rgba(25,24,22,.5),0 12px 28px -16px rgba(25,24,22,.28)}
[data-tour-window] > :not(.tour-chrome){flex:1;min-height:0}
.tour-chrome{flex:none;height:40px;display:flex;align-items:center;gap:14px;padding:0 14px;background:var(--page,#f5f3ef);border-bottom:1px solid var(--ph-line,#e3dfd7);font:500 12.5px/1 var(--sans,system-ui);color:var(--ink-2,#5f5a53)}
.tour-lights{display:flex;gap:8px}
.tour-lights i{width:12px;height:12px;border-radius:50%;background:#ec6a5e;box-shadow:inset 0 0 0 .5px rgba(0,0,0,.12)}
.tour-lights i+i{background:#f4bf4f}.tour-lights i+i+i{background:#61c554}
.tour-navs{display:flex;gap:10px}.tour-navs.is-end{margin-left:auto}
.tour-chrome svg{width:15px;height:15px;fill:none;stroke:var(--ink-3,#9c968c);stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.tour-url{flex:0 1 420px;margin-left:auto;display:flex;align-items:center;justify-content:center;gap:7px;height:26px;padding:0 14px;border-radius:7px;background:var(--ph,#fff);box-shadow:inset 0 0 0 1px var(--ph-line,#e3dfd7);font-weight:400;color:var(--ink-2,#5f5a53);white-space:nowrap;overflow:hidden}
.tour-url svg{width:12px;height:12px}
.tour-chrome[data-kind=app]{height:38px;justify-content:center;position:relative}
.tour-chrome[data-kind=app] .tour-lights{position:absolute;left:14px;top:13px}
.tour-chrome[data-kind=phone]{height:46px;justify-content:space-between;padding:0 26px;background:transparent;border:0;font:600 15px/1 var(--sans,system-ui);color:var(--ink,#191816)}
.tour-notch{width:120px;height:32px;border-radius:20px;background:#111}
.tour-status{display:flex;gap:4px}.tour-status i{width:16px;height:10px;border-radius:2px;background:var(--ink,#191816)}
[data-chrome=phone]{--tour-win-radius:54px;box-shadow:0 0 0 10px #111,0 0 0 11px #333,0 40px 90px -30px rgba(25,24,22,.55)}
[data-chrome=none]{--tour-win-radius:8px}
/* terminal: a warm charcoal window (tokens --tour-term-bg, --tour-term-bar, --tour-term-ink, --tour-term-dim) */
[data-chrome=terminal]{background:var(--tour-term-bg,#1d1b18);color:var(--tour-term-ink,#ebe5d9)}
.tour-chrome[data-kind=terminal]{height:38px;justify-content:center;position:relative;background:var(--tour-term-bar,#272420);border-bottom:1px solid rgba(255,255,255,.07);color:var(--tour-term-dim,#a39b8e);font-weight:500}
.tour-chrome[data-kind=terminal] .tour-lights{position:absolute;left:14px;top:13px}
.tour-chrome[data-kind=terminal] .tour-lights i{box-shadow:inset 0 0 0 .5px rgba(0,0,0,.3)}
/* windows inside the window: any [data-chrome] element in the product gets its own chrome and frame */
[data-tour-window] [data-chrome]{display:flex;flex-direction:column;overflow:hidden;border-radius:var(--tour-win-radius)}
[data-tour-window] [data-chrome] > :not(.tour-chrome){flex:1;min-height:0}

/* cursor and ripples (stage coordinates) */
.tour-cur{position:absolute;left:0;top:0;z-index:8;width:0;height:0;pointer-events:none;opacity:0;transform-origin:0 0}
.tour-cur svg{position:absolute;left:-1px;top:-1px;overflow:visible;filter:drop-shadow(0 1px 1.5px rgba(0,0,0,.35)) drop-shadow(0 3px 6px rgba(0,0,0,.12))}
.tour-cur .tour-arrow path{fill:#141312;stroke:#fff;stroke-width:1.3}
.tour-cur .tour-hand{left:-8px;top:-2px}
.tour-cur .tour-hand path{fill:#fff;stroke:#141312;stroke-width:1.1}
.tour-cur .tour-beam{left:-5px;top:-12px}
.tour-cur .tour-beam path{stroke:#141312;stroke-width:1.6;paint-order:stroke}
.tour-cur[data-look=light] .tour-arrow path{fill:#fff;stroke:#141312;stroke-width:1.1}
.tour-ring{position:absolute;left:0;top:0;z-index:7;width:46px;height:46px;margin:-23px 0 0 -23px;border-radius:50%;border:2.5px solid var(--tour-ring);background:color-mix(in srgb,var(--tour-ring) 18%,transparent);pointer-events:none;opacity:0}
/* pointer:'touch': a fingertip (44 window px, it zooms with the screen) instead of the arrow; tour.js sets its opacity and size */
.tour-touch{display:none;position:absolute;left:-22px;top:-22px;width:44px;height:44px;border-radius:50%;background:var(--tour-touch,rgba(112,112,120,.36));
  box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.62),0 0 0 1px rgba(20,19,18,.1),0 3px 12px -3px rgba(20,19,18,.32)}
.tour-cur.is-down .tour-touch{background:var(--tour-touch-down,rgba(92,92,100,.48));box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.7),0 0 0 1px rgba(20,19,18,.12),0 1px 5px -1px rgba(20,19,18,.3)}
.is-touch .tour-touch{display:block}
.is-touch .tour-cur svg{display:none!important}
.is-touch .tour-ring{width:44px;height:44px;margin:-22px 0 0 -22px;border:1.5px solid rgba(112,112,120,.55);background:none}
/* more than one pointer (steps with { by: 'agent' }): its own colour (--tour-agent) and a label tag; the person's
   cursor gets a tag too when pointers.main.label is set */
.tour-cur[data-look=agent] .tour-arrow path{fill:var(--tour-agent,#3b4bc8);stroke:#fff;stroke-width:1.4}
.tour-cur[data-look=agent] svg{filter:drop-shadow(0 1px 1.5px rgba(0,0,0,.25)) drop-shadow(0 0 7px color-mix(in srgb,var(--tour-agent,#3b4bc8) 45%,transparent))}
.tour-tag{position:absolute;left:13px;top:21px;display:flex;align-items:center;gap:6px;height:22px;padding:0 8px;border-radius:6px;background:var(--ink,#191816);color:#fff;
  font:600 11.5px/1 var(--sans,system-ui);letter-spacing:.01em;white-space:nowrap;box-shadow:0 4px 12px -4px rgba(0,0,0,.35)}
.tour-tag span{font:500 11px/1 var(--mono,ui-monospace,monospace);opacity:.82}
.tour-tag span[hidden]{display:none}
.tour-cur[data-look=agent] .tour-tag{background:var(--tour-agent,#3b4bc8)}
.tour-ring[data-who]:not([data-who=main]){--tour-ring:var(--tour-agent,#3b4bc8)}

/* chapter card: "02 / 05", a title with one italic word, one line */
.tour-card{position:absolute;z-index:6;left:var(--gutter,32px);bottom:var(--gutter,32px);width:min(calc(var(--su)*44),calc(100% - 2 * var(--gutter,32px)));
  padding:calc(var(--su)*1.8) calc(var(--su)*2.1) calc(var(--su)*2);background:var(--ph,#fff);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 20px 44px -24px rgba(25,24,22,.45);
  opacity:0;transform:translateY(calc((1 - var(--o,0)) * 10px));pointer-events:none}
.tour-card-n{font:500 max(10.5px,calc(var(--su)*1.15))/1 var(--sans,system-ui);letter-spacing:.14em;color:var(--ink-3,#9c968c)}
.tour-card h3{margin:calc(var(--su)*1) 0 calc(var(--su)*.75);font:400 max(25px,calc(var(--su)*3.7))/1 var(--serif,Georgia,serif);letter-spacing:-.018em;color:var(--ink,#191816)}
.tour-card h3 em{font-style:italic}
.tour-card p{margin:0;font:400 max(13.5px,calc(var(--su)*1.7))/1.45 var(--sans,system-ui);color:var(--ink-2,#5f5a53)}
.tour-card,.tour-cap{transition:translate .55s cubic-bezier(.2,.7,.2,1)}
.tour-card[data-dodge=hide]{opacity:0!important}
.tour-card[data-dodge=off]{display:none}
.tour-card-x{position:absolute;top:calc(var(--su)*.9);right:calc(var(--su)*.9);width:max(26px,calc(var(--su)*2.8));height:max(26px,calc(var(--su)*2.8));display:grid;place-items:center;
  padding:0;border:0;border-radius:50%;background:transparent;color:var(--ink-3,#9c968c);font:400 max(16px,calc(var(--su)*1.9))/1 var(--sans,system-ui);cursor:pointer;pointer-events:auto;opacity:.7}
.tour-card-x:hover{opacity:1;background:var(--ph-line,#e3dfd7);color:var(--ink,#191816)}
.tour-card-x:focus-visible{outline:2px solid var(--tour-ring,#c2643f);outline-offset:2px;opacity:1}
.is-stack .tour-card{left:4%;right:4%;width:auto;bottom:auto;top:var(--card-top);padding:calc(var(--su)*2) calc(var(--su)*2.4)}
[data-tour-root].is-play:not(.is-stack) .tour-card{bottom:calc(var(--gutter,32px) + 46px)}

/* caption line: burned into recordings, because X autoplays muted */
.tour-cap{position:absolute;z-index:7;left:50%;bottom:calc(var(--su)*4);margin:0;max-width:min(calc(var(--su)*72),calc(100% - 2 * var(--gutter,32px)));width:max-content;
  padding:calc(var(--su)*1.05) calc(var(--su)*1.9);border-radius:calc(var(--su)*.6);background:var(--tour-cap-bg);color:var(--tour-cap-ink);
  font:500 max(14px,calc(var(--su)*2.35))/1.3 var(--sans,system-ui);letter-spacing:-.005em;text-align:center;opacity:0;transform:translate(-50%,calc((1 - var(--o,0)) * 8px));pointer-events:none;text-wrap:balance}
.is-stack .tour-cap{bottom:calc(var(--su)*5)}
.is-stack.is-tall .tour-cap{bottom:auto;top:var(--cap-top)}
[data-tour-root].is-play .tour-cap{bottom:calc(var(--su)*4 + 46px)}

/* key caps */
.tour-keys{position:absolute;z-index:7;display:flex;gap:calc(var(--su)*.6);transform:translate(-50%,calc((1 - var(--o,0)) * 8px));opacity:0;pointer-events:none}
.tour-keys kbd{min-width:calc(var(--su)*5.4);height:calc(var(--su)*5.4);padding:0 calc(var(--su)*1.2);display:grid;place-items:center;border-radius:calc(var(--su)*.9);
  background:var(--ph,#fff);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 calc(var(--su)*.35) 0 var(--ph-line,#e3dfd7),0 14px 30px -16px rgba(25,24,22,.5);
  font:500 calc(var(--su)*2.4)/1 var(--sans,system-ui);color:var(--ink,#191816)}

/* play driver: one quiet bar */
.tour-ctl{position:absolute;z-index:9;left:50%;bottom:14px;transform:translateX(-50%);display:flex;align-items:center;gap:12px;width:min(620px,calc(100% - 28px));
  padding:7px 14px 7px 7px;border-radius:999px;background:color-mix(in srgb,var(--ph,#fff) 92%,transparent);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 12px 30px -18px rgba(25,24,22,.5);
  font:500 11.5px/1 var(--mono,ui-monospace,monospace);color:var(--ink-2,#5f5a53)}
.tour-pp{flex:none;width:32px;height:32px;border:0;border-radius:50%;display:grid;place-items:center;background:var(--ink,#191816);color:var(--page,#f5f3ef);cursor:pointer}
.tour-pp svg{width:13px;height:13px;fill:currentColor}
.tour-pp:focus-visible,.tour-scrub input:focus-visible{outline:2px solid var(--note,#c2643f);outline-offset:3px}
.tour-scrub{position:relative;flex:1;height:20px;display:flex;align-items:center}
.tour-scrub::before{content:"";position:absolute;left:0;right:0;height:2px;background:var(--ph-line,#e3dfd7)}
.tour-scrub::after{content:"";position:absolute;left:0;height:2px;width:calc(var(--v,0) * 100%);background:var(--ink,#191816)}
.tour-scrub i{position:absolute;top:5px;width:1px;height:10px;background:var(--ink-3,#9c968c)}
.tour-scrub input{position:relative;z-index:1;width:100%;margin:0;background:none;-webkit-appearance:none;appearance:none;cursor:pointer;height:20px}
.tour-scrub input::-webkit-slider-thumb{-webkit-appearance:none;width:12px;height:12px;border-radius:50%;background:var(--ink,#191816)}
.tour-scrub input::-moz-range-thumb{width:12px;height:12px;border:0;border-radius:50%;background:var(--ink,#191816)}
.tour-time{flex:none;min-width:84px;text-align:right}
[data-tour-root]:not(.is-begun) .tour-ctl{opacity:0;pointer-events:none}
.tour-ctl{transition:opacity .4s ease}
.is-stack .tour-time{display:none}

/* scroll driver: the auto-play switch, the only way to take over while it plays itself */
.tour-drift{position:absolute;z-index:9;right:var(--gutter,16px);bottom:16px;display:flex;align-items:center;gap:10px;padding:7px 8px 7px 14px;border-radius:999px;
  background:color-mix(in srgb,var(--ph,#fff) 88%,transparent);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 10px 26px -14px rgba(25,24,22,.45);
  font:500 12px/1 var(--sans,system-ui);color:var(--ink,#191816);cursor:pointer;user-select:none;transition:opacity .5s ease,transform .5s cubic-bezier(.2,.7,.2,1)}
.tour-drift input{position:absolute;opacity:0;pointer-events:none}
.tour-drift > i{position:relative;width:34px;height:20px;border-radius:999px;background:var(--ink,#191816);transition:background-color .25s}
.tour-drift > i::after{content:"";position:absolute;top:3px;left:17px;width:14px;height:14px;border-radius:50%;background:var(--page,#f5f3ef);transition:left .3s cubic-bezier(.2,.7,.2,1)}
.tour-drift:has(input:not(:checked)) > i{background:var(--rule,#d8d3c9)}
.tour-drift:has(input:not(:checked)) > i::after{left:3px}
.tour-drift:has(input:focus-visible){outline:2px solid var(--note,#c2643f);outline-offset:3px}
.tour-drift.is-gone{opacity:0;transform:translateY(8px);pointer-events:none}
.tour-say{position:absolute;right:0;bottom:calc(100% + 10px);width:max-content;max-width:min(260px,calc(100vw - 32px));padding:9px 12px;border-radius:8px;background:var(--ink,#191816);color:var(--page,#f5f3ef);
  font:500 12px/1.35 var(--sans,system-ui);opacity:0;transform:translateY(6px);pointer-events:none;transition:opacity .3s,transform .4s cubic-bezier(.2,.7,.2,1)}
.tour-drift.is-saying .tour-say{opacity:1;transform:none}
.tour-drift.is-saying{box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 0 0 4px color-mix(in srgb,var(--note,#c2643f) 35%,transparent)}

/* ?record: a clean stage of the chosen ratio, centred in the browser window, for Monet Shot to record */
html.tour-record,html.tour-record body{height:100%;overflow:hidden;background:#0e0e0d}
html.tour-record body :not([data-tour-root].is-record,[data-tour-root].is-record *,:has([data-tour-root].is-record)){display:none!important}   /* everything but the film (which may sit inside another section) */
html.tour-record .sf-note,html.tour-record .sf-spec,html.tour-record [data-tour-gate],html.tour-record [data-tour-hide-on-record]{display:none!important}
html.tour-record [data-tour-root].is-record{position:fixed;left:50%;top:50%;width:var(--rw);height:var(--rh)!important;transform:translate(-50%,-50%);z-index:2147483000;cursor:none}
html.tour-record .is-record [data-tour-stage]{position:absolute;inset:0;height:auto}

@media (prefers-reduced-motion:reduce){.tour-drift,.tour-drift *,.tour-say{transition:none}}
